// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank, Log} from "../src/Private_Bank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Private_Bank c;

    function setUp() public {
        c = new Private_Bank(address(new Log()));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.assume(amount <= 1e30);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        uint256 before = c.balances(actor);
        vm.assume(before == amount);

        vm.prank(actor);
        try c.CashOut(amount) {
            uint256 afterBal = c.balances(actor);
            assertTrue(afterBal == before - amount);
        } catch {
            assertTrue(true);
            return;
        }
    }
}
